{
  "wire_schema": "role_benchmark.player_action",
  "kind": "experiment",
  "portfolio": {
    "hypotheses": [
      {
        "hypothesis_id": "H1",
        "statement": "Period depends only on length, with T = 2π√(L/g), independent of mass and angle.",
        "confidence": 0.4
      },
      {
        "hypothesis_id": "H2",
        "statement": "Period depends on length and mass, e.g., T = 2π√(L/(g*m)) or similar power law.",
        "confidence": 0.3
      },
      {
        "hypothesis_id": "H3",
        "statement": "Period depends on length and release angle, e.g., T increases with angle.",
        "confidence": 0.3
      }
    ]
  },
  "experiment": {
    "intent": "Vary length while holding mass and angle constant to test length dependence.",
    "apparatus": "simple_pendulum",
    "controls": {
      "length_m": 1.0,
      "bob_mass_kg": 0.5,
      "release_angle_deg": 5.0
    },
    "readouts": ["period_s"],
    "replicates": 5,
    "forecasts": {
      "H1": {"period_s": 2.006},
      "H2": {"period_s": 2.006},
      "H3": {"period_s": 2.006}
    }
  },
  "final": null
}

